/* Terminal — a phosphor console: near-black glass, one green foreground,
   monospace everywhere, zero radius, glow instead of shadow.
   Conventions checked against terminal.css (MIT); no upstream code included. */
@theme {
	/* Phosphor green is simultaneously text, primary and chrome. There is no
	   "brand color" distinct from the only color the CRT can show. */
	--color-primary: #33ff66;
	/* Ink on phosphor is the glass itself — text on green inverts to black. */
	--color-primary-foreground: #0c1210;
	--color-surface: #0c1210;
	--color-surface-foreground: #33ff66;
	/* Panels sit a half-step off the glass, still green-tinted, never gray. */
	--color-surface-raised: #101b16;
	/* Dimmed phosphor for prompts, paths and secondary output. Body text is
	   never muted — if it matters, it burns at full brightness. */
	--color-muted: #1f7a44;
	--color-accent: #ffb000;
	--color-danger: #ff5555;
	/* Hairlines are dark green; a gray border would break the phosphor fiction. */
	--color-border: #1d3a2a;

	/* Radius does not exist on a CRT: every token is 0. */
	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;

	/* Depth is bloom, not cast shadow: a green halo with zero offset.
	   Amber and red elements bloom in their own phosphor. */
	--shadow-sm: 0 0 4px rgb(51 255 102 / 0.25);
	--shadow-md: 0 0 8px rgb(51 255 102 / 0.35);
	--shadow-lg: 0 0 16px rgb(51 255 102 / 0.45);
	--shadow-glow-amber: 0 0 8px rgb(255 176 0 / 0.4);
	--shadow-glow-red: 0 0 8px rgb(255 85 85 / 0.4);
	/* The blinking block cursor, for prompts and empty inputs. */
	--shadow-cursor: inset 0 0 0 8px rgb(51 255 102 / 0.9);

	/* Scanlines: the one gradient in the system, laid over the whole page. */
	--gradient-scanlines: repeating-linear-gradient(
		0deg,
		rgb(0 0 0 / 0.22) 0px,
		rgb(0 0 0 / 0.22) 1px,
		transparent 1px,
		transparent 3px
	);
}

/* Linear — dark, dense, engineered calm. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #5e6ad2;
	--color-primary-foreground: #ffffff;
	--color-surface: #08090a;
	--color-surface-foreground: #f7f8f8;
	--color-surface-raised: #131416;
	--color-muted: #8a8f98;
	--color-accent: #26b5ce;
	--color-danger: #eb5757;
	--color-border: #26282d;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	--shadow-sm: 0 1px 2px rgb(0 0 0 / 0.5);
	--shadow-md: 0 4px 16px rgb(0 0 0 / 0.5);
	--shadow-lg: 0 16px 48px rgb(0 0 0 / 0.6);
}

/* Neo Brutalism — raw anti-polish: 2px black outlines, hard offset shadows, flat
   saturated blocks, loud uppercase type. Nothing blurs, nothing fades, nothing glows.
   Proportions checked against neobrutalism.dev (MIT); no upstream code included. */
@theme {
	/* Yellow is the workhorse fill: hero blocks, primary buttons, highlights. */
	--color-primary: #ffdc58;
	/* Ink on any fill here is near-black — white text never appears on color. */
	--color-primary-foreground: #111111;
	--color-surface: #fffdf5;
	--color-surface-foreground: #111111;
	/* Cards are pure white so the black outline and hard shadow read at full contrast. */
	--color-surface-raised: #ffffff;
	--color-muted: #52525b;
	/* Pink is the second sticker color: badges, tags, hover fills. */
	--color-accent: #ffb3c7;
	--color-danger: #ff5d5d;
	/* The border IS black: every interactive element is outlined, never tinted. */
	--color-border: #111111;

	/* Secondary sticker tints. Use one or two per screen, never all at once. */
	--color-cyan: #a5f3fc;
	--color-lime: #b8f35a;

	/* The radius scale barely exists: sm 0 / md 4 / lg 6, and xl+ stay at 6 —
	   corners never get rounder. Pills opt out entirely with --radius-full. */
	--radius-sm: 0px;
	--radius-md: 4px;
	--radius-lg: 6px;
	--radius-xl: 6px;
	--radius-2xl: 6px;
	--radius-full: 9999px;

	/* Hard offset shadows, zero blur, pure ink. The offset IS the elevation. */
	--shadow-sm: 2px 2px 0 #111111;
	--shadow-md: 4px 4px 0 #111111;
	--shadow-lg: 8px 8px 0 #111111;
	/* Hover pushes the block further from the page; active slams it flat. */
	--shadow-hover: 6px 6px 0 #111111;
	--shadow-active: 0 0 0 #111111;
}

/* Doodle Pop — lime × black sticker energy: thick ink borders, hard offset shadows,
 * polka-dot textures, coral/lavender/sky pastel pops. Original Vetta preset. */
@theme {
	--color-primary: #d6f437;
	--color-primary-foreground: #111111;
	--color-surface: #c8e93c;
	--color-surface-foreground: #111111;
	--color-surface-raised: #ffffff;
	--color-muted: #55584a;
	--color-accent: #f4794f;
	--color-danger: #ef3b5d;
	--color-border: #111111;
	--color-cream: #f2f0e6;
	--color-lavender: #b39df3;
	--color-sky: #8ed8e8;
	--color-ink: #111111;

	--radius-sm: 8px;
	--radius-md: 12px;
	--radius-lg: 16px;
	--radius-xl: 20px;
	--radius-2xl: 28px;

	--shadow-sm: 2px 2px 0 #111111;
	--shadow-md: 4px 4px 0 #111111;
	--shadow-lg: 7px 7px 0 #111111;
}

/* Memphis — eighties geometric rebellion: flat clashing color blocks, squiggles,
   polka dots and hard-edged shapes on white. Original curated spec for this
   collection (MIT). */
@theme {
	--color-primary: #ff6b6b; /* coral red — the loudest block: hero fills, primary chips */
	--color-primary-foreground: #ffffff; /* white labels on coral, always large & bold */
	--color-surface: #ffffff; /* the clean white stage — confetti needs a white ground */
	--color-surface-foreground: #17171c; /* near-black ink for text, patterns, outlines */
	--color-surface-raised: #fff9f0; /* warm cream for panels that must sit back */
	--color-muted: #7a7a85; /* cool gray for secondary text only */
	--color-accent: #00c2c7; /* teal — the clash partner: blocks, links, highlights */
	--color-danger: #e5484d;
	--color-border: #17171c; /* ink — outlines on interactive pieces, pattern strokes */
	/* The second pair of clashing tints. Both are fills, never text colors. */
	--color-mustard: #ffce4f;
	--color-violet-pop: #9b5de5;

	/* Mixed on purpose: blocks stay hard (0), chips get slightly round (6–16) —
	   blocky geometry with a few soft corners, never pill-round everything. */
	--radius-sm: 0px;
	--radius-md: 6px;
	--radius-lg: 10px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	/* Hard flat ink offsets with zero blur — the "sticker" depth for interactive
	   and tilted pieces. Static color blocks stay completely flat. */
	--shadow-sm: 3px 3px 0 #17171c;
	--shadow-md: 5px 5px 0 #17171c;
	--shadow-lg: 8px 8px 0 #17171c;
}

/* Cursor — warm-graphite AI editor dark; brand voltage is Cursor Orange. Palette adapted from awesome-design-md (MIT). */
@theme {
	--color-primary: #f54e00;
	--color-primary-foreground: #ffffff;
	--color-surface: #1e1f22;
	--color-surface-foreground: #e8eaed;
	--color-surface-raised: #26282c;
	--color-muted: #9aa0a6;
	--color-accent: #c0a8dd;
	--color-danger: #f87171;
	--color-border: #33363b;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	--shadow-sm: 0 1px 2px rgb(0 0 0 / 0.4);
	--shadow-md: 0 4px 16px rgb(0 0 0 / 0.45);
	--shadow-lg: 0 16px 48px rgb(0 0 0 / 0.55);
}

/* Stripe — polished fintech, blurple on airy blue-gray. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #635bff;
	--color-primary-foreground: #ffffff;
	--color-surface: #f6f9fc;
	--color-surface-foreground: #0a2540;
	--color-surface-raised: #ffffff;
	--color-muted: #425466;
	--color-accent: #00d4ff;
	--color-danger: #df1b41;
	--color-border: #e6ebf1;

	--radius-sm: 6px;
	--radius-md: 8px;
	--radius-lg: 12px;
	--radius-xl: 16px;
	--radius-2xl: 24px;

	--shadow-sm: 0 2px 5px -1px rgb(50 50 93 / 0.12), 0 1px 3px -1px rgb(0 0 0 / 0.15);
	--shadow-md: 0 6px 12px -2px rgb(50 50 93 / 0.2), 0 3px 7px -3px rgb(0 0 0 / 0.15);
	--shadow-lg: 0 13px 27px -5px rgb(50 50 93 / 0.25), 0 8px 16px -8px rgb(0 0 0 / 0.3);
}

/* Apple macOS — the Mac desktop layer: translucent menu bar, vibrancy sidebar,
   traffic-light windows and large soft window shadows. Factual macOS platform
   conventions; color values are community-sampled (Apple publishes no fixed hex
   for the user-configurable accent). Original descriptions. Not affiliated with
   or endorsed by Apple Inc. */
@theme {
	--color-primary: #0a7cff; /* macOS accent blue, community-sampled — selection and the one filled control */
	--color-primary-foreground: #ffffff;
	--color-surface: #ffffff; /* window content area */
	--color-surface-foreground: #1d1d1f; /* label ink */
	--color-surface-raised: #f0f0f2; /* sidebar / toolbar chrome gray */
	--color-muted: #6e6e73; /* secondaryLabel */
	--color-accent: #28cd41; /* macOS systemGreen — differs from iOS #34C759 */
	--color-danger: #ff453a; /* systemRed — destructive only */
	--color-border: #d5d5d7; /* chrome and row hairline */

	/* Window chrome, and only there */
	--color-traffic-close: #ff5f57;
	--color-traffic-min: #febc2e;
	--color-traffic-max: #28c840;
	--color-menubar: rgb(246 246 248 / 0.72); /* translucent menu bar fill */
	--color-sidebar: rgb(240 240 244 / 0.8); /* vibrancy sidebar fill */
	--blur-vibrancy: 24px;

	--radius-sm: 6px;  /* push buttons, inputs */
	--radius-md: 8px;  /* rows, small cards */
	--radius-lg: 12px; /* windows, large cards */
	--radius-xl: 16px;
	--radius-2xl: 20px;

	/* Windows float high above the desktop: big, soft, diffuse. */
	--shadow-sm: 0 1px 3px rgb(0 0 0 / 0.08);
	--shadow-md: 0 8px 24px rgb(0 0 0 / 0.14);
	--shadow-lg: 0 24px 64px rgb(0 0 0 / 0.22);
}

/* Apple HIG — iOS system palette (light column) and grouped-list chrome, from Apple's public Human Interface Guidelines. Factual values, original descriptions. Not affiliated with or endorsed by Apple Inc. */
@theme {
	--color-primary: #007aff; /* systemBlue — the tint: links, selected controls, one filled action */
	--color-primary-foreground: #ffffff;
	--color-surface: #f2f2f7; /* systemGroupedBackground — the page behind the groups */
	--color-surface-foreground: #000000; /* label */
	--color-surface-raised: #ffffff; /* secondarySystemGroupedBackground — grouped card fill */
	--color-muted: rgb(60 60 67 / 0.6); /* secondaryLabel */
	--color-accent: #5856d6; /* systemIndigo — second tint, used as sparingly as primary */
	--color-danger: #ff3b30; /* systemRed — destructive only */
	--color-border: #c6c6c8; /* opaqueSeparator */

	--radius-sm: 8px;
	--radius-md: 12px;
	--radius-lg: 16px;
	--radius-xl: 20px;
	--radius-2xl: 28px;

	--shadow-sm: 0 1px 2px rgb(0 0 0 / 0.06);
	--shadow-md: 0 4px 12px rgb(0 0 0 / 0.08);
	--shadow-lg: 0 12px 32px rgb(0 0 0 / 0.12);
}

/* Spotify — near-black stage, one electric green, pill everything. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #1db954;
	--color-primary-foreground: #000000;
	--color-surface: #121212;
	--color-surface-foreground: #ffffff;
	--color-surface-raised: #1f1f1f;
	--color-muted: #a7a7a7;
	--color-accent: #1ed760;
	--color-danger: #f15e6c;
	--color-border: #2a2a2a;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	--shadow-sm: 0 2px 4px rgb(0 0 0 / 0.4);
	--shadow-md: 0 8px 24px rgb(0 0 0 / 0.5);
	--shadow-lg: 0 16px 56px rgb(0 0 0 / 0.7);
}

/* Meadow Buddies — soft woodland fitness. Original implementation; reference image excluded. */
@theme {
	--color-primary: #492724;
	--color-primary-foreground: #fffdf8;
	--color-surface: #f8f9f5;
	--color-surface-foreground: #2d2423;
	--color-surface-raised: #ffffff;
	--color-muted: #6f756a;
	--color-accent: #a5bf7d;
	--color-danger: #a45c40;
	--color-border: #e8ece5;
	--color-sage-light: #dce7bf;
	--color-sage-dark: #526b43;
	--color-apricot: #f9cc87;
	--color-apricot-light: #fff0d1;
	--color-honey: #da941b;
	--color-ochre: #856222;
	--color-mist: #f2f6f6;
	--color-stage-end: #cbd6cd;
	--color-stone: #89806d;
	--font-sans: "Avenir Next", "Trebuchet MS", Arial, sans-serif;
	--radius-sm: 8px;
	--radius-md: 16px;
	--radius-lg: 22px;
	--radius-xl: 34px;
	--radius-2xl: 44px;
	--shadow-sm: 0 3px 8px rgb(65 82 46 / 0.04);
	--shadow-md: 0 10px 24px rgb(65 82 46 / 0.06);
	--shadow-lg: 0 28px 44px -18px rgb(65 82 46 / 0.22);
}

/* Raycast — near-black command bar; depth is a surface ladder, never a shadow. Adapted from awesome-design-md (MIT). */
@theme {
	--color-primary: #ffffff;
	--color-primary-foreground: #000000;
	--color-surface: #0d0d0d;
	--color-surface-foreground: #f4f4f6;
	--color-surface-raised: #121212;
	--color-muted: #9c9c9d;
	--color-accent: #ff6161;
	--color-danger: #ff453a;
	--color-border: #242728;

	--radius-sm: 4px;
	--radius-md: 8px;
	--radius-lg: 10px;
	--radius-xl: 16px;
	--radius-2xl: 16px;

	/* Raycast casts no drop shadows — the ladder carries all depth.
	   Tokens are kept for contract compatibility and resolve to nothing. */
	--shadow-sm: 0 0 0 rgb(0 0 0 / 0);
	--shadow-md: 0 0 0 rgb(0 0 0 / 0);
	--shadow-lg: 0 0 0 rgb(0 0 0 / 0);
}

/* Notion — quiet warm-gray writing surface, ink first. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #2383e2;
	--color-primary-foreground: #ffffff;
	--color-surface: #ffffff;
	--color-surface-foreground: #37352f;
	--color-surface-raised: #f7f6f3;
	--color-muted: #787774;
	--color-accent: #d9730d;
	--color-danger: #eb5757;
	--color-border: #e9e9e7;

	--radius-sm: 3px;
	--radius-md: 4px;
	--radius-lg: 6px;
	--radius-xl: 8px;
	--radius-2xl: 12px;

	--shadow-sm: 0 1px 2px rgb(15 15 15 / 0.06);
	--shadow-md: 0 2px 6px rgb(15 15 15 / 0.08), 0 0 0 1px rgb(15 15 15 / 0.03);
	--shadow-lg: 0 8px 24px rgb(15 15 15 / 0.12), 0 0 0 1px rgb(15 15 15 / 0.04);
}

/* Pixel 8-bit — game-cartridge UI: flat NES palette, thick near-black pixel
   borders, block shadows made of box-shadow steps, zero radius anywhere.
   Palette and border conventions checked against NES.css (MIT); no upstream
   code included. */
@theme {
	/* Green is the action color: primary buttons, confirm, HP, positive stats. */
	--color-primary: #92cc41;
	/* Ink on any fill is the near-black border color itself — the cartridge
	   palette has exactly one dark: #212529. */
	--color-primary-foreground: #212529;
	--color-surface: #ffffff;
	--color-surface-foreground: #212529;
	/* Raised panels are the faint cartridge gray, never a gradient. */
	--color-surface-raised: #f8f8f8;
	--color-muted: #999999;
	/* Yellow is the pickup color: gold, MP, warnings, coin counters. */
	--color-accent: #f7d51d;
	--color-danger: #e76e55;
	/* One border color for the whole world: the near-black ink. */
	--color-border: #212529;

	/* Two more cartridge hues: blue for secondary actions/links, gray for
	   pressed bevels and disabled states (NES.css conventions). */
	--color-blue: #209cee;
	--color-bevel: #adafbc;

	/* The grid has no curves: every radius is 0. */
	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;

	/* Block shadows drawn from box-shadow steps — each tier is the full
	   silhouette offset down-right plus two side copies that fill the corner,
	   so the shadow is a solid pixel block, not a blur. */
	--shadow-sm: 2px 2px 0 #212529, 2px 0 0 #212529, 0 2px 0 #212529;
	--shadow-md: 4px 4px 0 #212529, 4px 0 0 #212529, 0 4px 0 #212529;
	--shadow-lg: 8px 8px 0 #212529, 8px 0 0 #212529, 0 8px 0 #212529;
	/* Pressed: the block collapses and the element sits flush on the page. */
	--shadow-pressed: 0 0 0 #212529;
}

/* Vercel — stark black-on-white monochrome, one blue. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #000000;
	--color-primary-foreground: #ffffff;
	--color-surface: #ffffff;
	--color-surface-foreground: #000000;
	--color-surface-raised: #fafafa;
	--color-muted: #666666;
	--color-accent: #0070f3;
	--color-danger: #ee0000;
	--color-border: #eaeaea;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	--shadow-sm: 0 1px 2px rgb(0 0 0 / 0.06);
	--shadow-md: 0 4px 12px rgb(0 0 0 / 0.08);
	--shadow-lg: 0 12px 32px rgb(0 0 0 / 0.12);
}

/* Supabase — light console with the emerald identity; depth is borders, not shadows. Adapted from awesome-design-md (MIT). */
@theme {
	--color-primary: #3ecf8e;
	--color-primary-foreground: #003a1d;
	--color-surface: #ffffff;
	--color-surface-foreground: #1c1c1c;
	--color-surface-raised: #fafafa;
	--color-muted: #6b7280;
	--color-accent: #7c66a1;
	--color-danger: #e5484d;
	--color-border: #e5e7eb;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	--shadow-sm: 0 1px 2px rgb(0 0 0 / 0.05);
	--shadow-md: 0 2px 8px rgb(0 0 0 / 0.08);
	--shadow-lg: 0 8px 24px rgb(0 0 0 / 0.12);
}

/* Organic — grounded and grown, not manufactured: linen ground, sage and
   terracotta, extra-large radii, warm shallow shadows. Original curated spec
   for this collection (MIT). */
@theme {
	--color-primary: #4f7a5a; /* moss green — CTAs, links, the "grown" voice */
	--color-primary-foreground: #f6f3ec; /* linen text on moss, never pure white */
	--color-surface: #f6f3ec; /* linen — the unbleached page */
	--color-surface-foreground: #2f3a2f; /* deep moss ink */
	--color-surface-raised: #ffffff; /* product cards and panels */
	--color-muted: #7d8577; /* lichen gray-green for secondary text */
	--color-accent: #c97b5a; /* terracotta — second voice: prices, highlights, stamps */
	--color-danger: #b0563f; /* fired clay, reads as a warm error */
	--color-border: #e3ded2; /* oat hairline */
	/* Sand is the mid earth tone: hero washes, dividers, chip fills. */
	--color-sand: #ece5d8;

	/* Everything grew, so nothing is sharp: the scale starts at 10px and
	   product cards live at 20–28px. Pills are welcome everywhere. */
	--radius-sm: 10px;
	--radius-md: 14px;
	--radius-lg: 20px;
	--radius-xl: 24px;
	--radius-2xl: 28px;

	/* Warm and shallow: shadows come from an overcast sky, not a lamp. */
	--shadow-sm: 0 1px 2px rgb(47 58 47 / 0.06);
	--shadow-md: 0 4px 14px rgb(47 58 47 / 0.08);
	--shadow-lg: 0 14px 32px rgb(47 58 47 / 0.10);
}

/* Headspace — warm sunrise calm, rounded everything, friendly ink. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #f47d31;
	--color-primary-foreground: #ffffff;
	--color-surface: #fefaf3;
	--color-surface-foreground: #2d2c41;
	--color-surface-raised: #ffffff;
	--color-muted: #7a7889;
	--color-accent: #5a77d6;
	--color-danger: #e5484d;
	--color-border: #efe4d5;

	--radius-sm: 10px;
	--radius-md: 14px;
	--radius-lg: 18px;
	--radius-xl: 24px;
	--radius-2xl: 32px;

	--shadow-sm: 0 2px 6px rgb(45 44 65 / 0.06);
	--shadow-md: 0 8px 20px rgb(45 44 65 / 0.08);
	--shadow-lg: 0 20px 48px rgb(45 44 65 / 0.12);
}

/* IBM Carbon — adapted from the IBM Carbon Design System (Apache-2.0, carbondesignsystem.com). Factual token values, original descriptions. Not affiliated with or endorsed by IBM. */
@theme {
	--color-primary: #0f62fe; /* Blue 60 — the one action color */
	--color-primary-foreground: #ffffff;
	--color-surface: #f4f4f4; /* Gray 10 — the page */
	--color-surface-foreground: #161616; /* Gray 100 — ink, also the dark shell */
	--color-surface-raised: #ffffff; /* tiles, tables, panels on the page */
	--color-muted: #525252; /* Gray 70 — helper text, table headers */
	--color-accent: #42be65; /* Green 40 — success / healthy */
	--color-danger: #da1e28; /* Red 60 — failure, destructive */
	--color-border: #e0e0e0; /* Gray 20 — every structural hairline */

	--radius-sm: 0px;
	--radius-md: 2px;
	--radius-lg: 2px;
	--radius-xl: 4px;
	--radius-2xl: 4px;

	--shadow-sm: 0 1px 2px rgb(0 0 0 / 0.05);
	--shadow-md: 0 2px 6px rgb(0 0 0 / 0.1);
	--shadow-lg: 0 4px 12px rgb(0 0 0 / 0.16);
}

/* GitHub — dark dimmed code habitat, green actions, blue links. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #238636;
	--color-primary-foreground: #ffffff;
	--color-surface: #0d1117;
	--color-surface-foreground: #e6edf3;
	--color-surface-raised: #161b22;
	--color-muted: #8b949e;
	--color-accent: #58a6ff;
	--color-danger: #f85149;
	--color-border: #30363d;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 6px;
	--radius-xl: 8px;
	--radius-2xl: 12px;

	--shadow-sm: 0 1px 0 rgb(1 4 9 / 0.6);
