/* Swiss Grid — International Typographic Style: white ground, ink text, one Swiss
   red, a strict visible grid, sans type only, zero ornament. Original curated spec
   for this collection (MIT). */
@theme {
	--color-primary: #e32636; /* Swiss red — the page's only color: numbers, markers, the one real action */
	--color-primary-foreground: #ffffff;
	--color-surface: #ffffff; /* the white ground */
	--color-surface-foreground: #111111; /* ink — text and structure share it */
	--color-surface-raised: #f7f7f7; /* the only tonal step: image plates and pull blocks */
	--color-muted: #6b6b6b; /* secondary text, captions, folios */
	/* The accent is ink black on purpose: the grid, the rules and the display type
	   carry it. A second hue would dilute the single Swiss red. */
	--color-accent: #111111;
	--color-danger: #cc2b1d;
	/* The border is the grid: black 1px hairlines are the structure of every layout. */
	--color-border: #111111;

	/* Corners do not exist. Every radius is 0; a rounded rectangle is off-style. */
	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;

	/* The page has no light source: separation comes from the grid, not elevation. */
	--shadow-sm: none;
	--shadow-md: none;
	--shadow-lg: none;
}

/* Geometric Bold — Bauhaus / constructivist poster. Pure primaries, no soft anything.
   Palette adapted from the StyleKit「几何大胆风」guide (see meta.json origin). */
@theme {
	--color-primary: #000000;
	--color-primary-foreground: #ffffff;
	--color-surface: #ffffff;
	--color-surface-foreground: #000000;
	--color-surface-raised: #ffffff;
	--color-muted: #6c3b00;
	--color-accent: #0000ff;
	--color-danger: #ff0000;
	--color-border: #000000;

	/* Shape palette — the four poster inks. Use as full blocks, never as tints. */
	--color-block-red: #ff0000;
	--color-block-blue: #0000ff;
	--color-block-yellow: #ffff00;
	--color-block-earth: #6c3b00;

	/* Foregrounds that stay legible on each block. */
	--color-block-red-foreground: #ffffff;
	--color-block-blue-foreground: #ffffff;
	--color-block-yellow-foreground: #000000;
	--color-block-earth-foreground: #ffffff;

	/* Two radii only: a shape is either a hard rectangle or a perfect circle. */
	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;
	--radius-full: 9999px;

	/* Structure comes from 4px borders. Border widths, not elevation. */
	--border-width-hair: 2px;
	--border-width-base: 4px;
	--border-width-heavy: 8px;

	/* No blur, ever. Floating layers get a hard offset block so they still read
	   as "above" without introducing soft depth. */
	--shadow-sm: none;
	--shadow-md: none;
	--shadow-lg: 8px 8px 0 0 #000000;
}

