	--color-primary-foreground: #ffffff;
	--color-surface: #050510; /* the night: near-black navy, never pure black */
	--color-surface-foreground: #f4f6ff;
	--color-surface-raised: #0d0d1f; /* the card step above the night */
	--color-muted: #8b93c7; /* periwinkle — secondary text stays cool, not gray */
	--color-accent: #00dc82; /* aurora green — live states, one highlight */
	--color-danger: #ff5470;
	--color-border: rgb(124 58 237 / 0.25); /* faint violet structure */

	/* The aurora field: three hues staged as blurred radial light. */
	--gradient-aurora-1: radial-gradient(closest-side, rgb(124 58 237 / 0.5), transparent 72%);
	--gradient-aurora-2: radial-gradient(closest-side, rgb(0 220 130 / 0.34), transparent 72%);
	--gradient-aurora-3: radial-gradient(closest-side, rgb(244 114 182 / 0.3), transparent 72%);
	--blur-aurora: 80px;
	--color-aurora-pink: #f472b6; /* the third hue: backdrop-first, UI garnish */

	/* Ambient halos — wide, low-alpha, no hot core. */
	--shadow-sm: 0 0 20px rgb(124 58 237 / 0.12);
	--shadow-md: 0 0 40px rgb(124 58 237 / 0.25);
	--shadow-lg: 0 0 80px rgb(124 58 237 / 0.3);
	--shadow-glow-green: 0 0 32px rgb(0 220 130 / 0.28);
	--shadow-glow-pink: 0 0 32px rgb(244 114 182 / 0.25);

