/* Wise — sage canvas, white cards, one lime-green action. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #9fe870;
	--color-primary-foreground: #0e0f0c;
	--color-surface: #e8ebe6;
	--color-surface-foreground: #0e0f0c;
	--color-surface-raised: #ffffff;
	--color-muted: #454745;
	--color-accent: #ffeb69;
	--color-danger: #d03238;
	--color-border: #e0e3dd;

	--radius-sm: 8px;
	--radius-md: 12px;
	--radius-lg: 16px;
	--radius-xl: 24px;
	--radius-2xl: 32px;

	--shadow-sm: 0 1px 2px rgb(14 15 12 / 0.05);
	--shadow-md: 0 6px 16px rgb(14 15 12 / 0.07);
	--shadow-lg: 0 16px 40px rgb(14 15 12 / 0.12);
}
